/**
 * Mock 默认城市字典：四直辖市分别列出（与后端各直辖市自成一级行政区的浏览体感一致）、
 * 港澳台拆三组（组标题中文，条目用核实后的 API 英文名；旧中文历史值不迁移，仍正常展示/删除）、
 * 不含海外长组（海外仅经精选区或搜索可达）。
 */
export const Mock默认城市字典: 省份分组[] = [
  ...['北京', '上海', '天津', '重庆'].map((城) => ({ 省: 城, 城市: [城] })),
  ...城市字典.filter((组) => 组.省 !== '直辖市' && 组.省 !== '港澳台' && 组.省 !== '海外'),
  { 省: '台湾省', 城市: ['Taiwan', 'Taipei'] },
  { 省: '香港特别行政区', 城市: ['Hong Kong'] },
  { 省: '澳门特别行政区', 城市: ['Macau'] },
];

/** 原海外模拟记录：旧 城市字典 的海外长组内容，继续进搜索字典（搜索范围不因默认页收窄） */
const 原海外模拟城市们 =
  城市字典.find((组) => 组.省 === '海外')?.城市 ?? [];

/**
 * Mock 城市搜索字典：默认字典 + 原海外模拟记录 + 海外精选名，按城市名去重。
 * 三个 Mock 搜索读这一份；国内精选名已全部在默认字典里（旧中文名即别名），无需另列。
 * Task 6：海外精选 display_name 是目录规范英文名，与旧中文模拟名并存 ——
 * 搜索经 Mock城市搜索结果 做别名/规范名双匹配并按规范名去重，同名城市绝不重复上屏。
 */
export const Mock城市搜索字典: 省份分组[] = [
  ...Mock默认城市字典,
  {
    省: '海外',
    城市: Array.from(new Set([...原海外模拟城市们, ...海外精选城市.map((项) => 项.display_name)])),
  },
];

/**
 * Task 6：Mock 城市搜索适配 —— 旧中文名（别名）与目录规范名都能命中，
 * 返回按规范名去重后的规范名列表（同名城市只出一条）。省名也算命中
 * （输「浙」出浙江全省），不发请求。
 */
export function Mock城市搜索结果(词: string): string[] {
  const 搜索词 = 词.trim();
  if (搜索词 === '') return [];
  const 见过 = new Set<string>();
  const 结果: string[] = [];
  for (const 组 of Mock城市搜索字典) {
    if (组.省.includes(搜索词)) {
      for (const 城 of 组.城市) {
        const 名 = 规范精选城市名称(城);
        if (!见过.has(名)) {
          见过.add(名);
          结果.push(名);
        }
      }
      continue;
    }
    for (const 城 of 组.城市) {
      const 名 = 规范精选城市名称(城);
      if (见过.has(名)) continue;
      if (城.includes(搜索词) || 名.includes(搜索词)) {
        见过.add(名);
        结果.push(名);
      }
    }
  }
  return 结果;
}

